lib = '''from collections import Counter

def uniform_rows(grid):
    """Indices of rows that are one color throughout."""
    return [i for i, row in enumerate(grid) if len(set(row)) == 1]

def uniform_cols(grid):
    """Indices of columns that are one color throughout."""
    return [j for j in range(len(grid[0])) if len({row[j] for row in grid}) == 1]

def divider_run(grid, axis="row"):
    """(start, end) of the maximal run of uniform lines whose single color appears nowhere else in the grid, or None."""
    if axis == "row":
        lines = grid
        uni = uniform_rows(grid)
        total = len(grid[0])
    else:
        lines = [[grid[i][j] for i in range(len(grid))] for j in range(len(grid[0]))]
        uni = uniform_cols(grid)
        total = len(grid)
    cnt = Counter(v for line in lines for v in line)
    runs = []
    i = 0
    while i < len(lines):
        if i in uni:
            j = i
            while j + 1 in uni and lines[j + 1][0] == lines[i][0]:
                j += 1
            c = lines[i][0]
            if cnt[c] == (j - i + 1) * total:
                runs.append((i, j))
            i = j + 1
        else:
            i += 1
    return runs[0] if len(runs) == 1 else None

def section_overlap(grid, fill=2):
    """Split the grid at its divider run (kept with the second section), end-align the sections, and keep each cell of the first section (as fill) only where the aligned cell of the second is nonzero."""
    d0, d1 = divider_run(grid, "row") if divider_run(grid, "row") else divider_run(grid, "col")
    if divider_run(grid, "row"):
        first, second = [r[:] for r in grid[:d0]], grid[d0:]
    else:
        cols = [[grid[i][j] for i in range(len(grid))] for j in range(len(grid[0]))]
        first = [[cols[j][i] for j in range(d0)] for i in range(len(grid))]
        second = [[cols[j][i] for j in range(d0, len(grid[0]))] for i in range(len(grid))]
    off = len(second) - len(first)
    h, w = len(first), len(first[0])
    return [[fill if first[i][j] and second[i + off][j] else 0 for j in range(w)] for i in range(h)]
'''
